mount.import:
import { securityHeaders } from './headers.js';
import { cors } from './cors.js';
import { rateLimit } from './rate-limit.js';
import { validate, object, string } from './validate.js';

mount.use:
// Gardes transverses AVANT le parsing du corps et les routes.
app.disable('x-powered-by');
app.use(securityHeaders());
app.use(cors({ origins: (process.env.CORS_ORIGINS ?? 'http://localhost:5173').split(',') }));
app.use(rateLimit({ windowMs: 60_000, max: Number(process.env.RATE_LIMIT_MAX ?? 100) }));
// Valider une route : app.post('/x', validate(object({ name: string({ min: 1 }) })), handler);
